// Data layer. Reads the JSON generated by scripts/sync.ts (GitHub Actions).
// Tokens never reach the browser — the site only fetches static files.
import { useEffect, useState } from "react";

export interface Project {
  name: string; title: string; description: string | null; url: string; demo: string | null;
  preview: string | null; kind: string; tech: string[]; stars: number; pushedAt: string;
}
export interface ProjectsData {
  generatedAt: string;
  featured: { ai: Project | null; extension: Project | null };
  more: Project[];
}
export interface GitHubData {
  generatedAt: string; profileUrl: string; login: string;
  publicRepos: number; stars: number; followers: number; following: number;
  languages: { name: string; percent: number }[];
  recent: { name: string; url: string; pushedAt: string }[];
  contributions: { total: number; weeks: { date: string; count: number }[][] } | null;
}
export interface MediumData {
  configured: boolean; error?: string;
  articles: { title: string; url: string; date: string; summary: string }[];
}

export type Async<T> = { status: "loading" } | { status: "error" } | { status: "ready"; data: T };

// Resolves files in public/ against the deploy base path; absolute URLs pass through.
export const asset = (path: string) => (/^https?:/.test(path) ? path : import.meta.env.BASE_URL + path);

const cache = new Map<string, Promise<unknown>>();

function load<T>(file: string): Promise<T> {
  if (!cache.has(file)) {
    cache.set(file, fetch(asset(`data/${file}`)).then((r) => {
      if (!r.ok) throw new Error(String(r.status));
      return r.json();
    }));
  }
  return cache.get(file) as Promise<T>;
}

function useData<T>(file: string): Async<T> {
  const [state, setState] = useState<Async<T>>({ status: "loading" });
  useEffect(() => {
    let live = true;
    load<T>(file)
      .then((data) => live && setState({ status: "ready", data }))
      .catch(() => live && setState({ status: "error" }));
    return () => { live = false; };
  }, [file]);
  return state;
}

export const useProjects = () => useData<ProjectsData>("projects.json");
export const useGitHub = () => useData<GitHubData>("github.json");
export const useMedium = () => useData<MediumData>("medium.json");

export const fmtDate = (iso: string) =>
  new Date(iso).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" });
